create extension if not exists pgcrypto;
create type public.app_role as enum ('ADMIN','EMPLOYEE');
create type public.task_priority as enum ('LOW','MEDIUM','HIGH','URGENT');
create type public.submission_kind as enum ('CHECKBOX','TEXT','CAMERA');
create type public.task_status as enum ('ASSIGNED','IN_PROGRESS','SUBMITTED','PENDING_APPROVAL','COMPLETED','REJECTED');
create table public.departments(id uuid primary key default gen_random_uuid(), name text not null unique, created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role public.app_role not null default 'EMPLOYEE', department_id uuid references public.departments(id) on delete set null, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tasks(id uuid primary key default gen_random_uuid(), title text not null check(length(trim(title)) between 1 and 120), description text not null default '', department_id uuid references public.departments(id) on delete set null, assigned_by uuid not null references public.profiles(id), priority public.task_priority not null default 'MEDIUM', due_at timestamptz, submission_type public.submission_kind not null default 'CHECKBOX', recurrence_rule jsonb, archived_at timestamptz, created_at timestamptz not null default now());
create table public.task_assignments(id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id) on delete cascade, employee_id uuid not null references public.profiles(id), department_id uuid references public.departments(id) on delete set null, status public.task_status not null default 'ASSIGNED', instance_date date, assigned_at timestamptz not null default now(), started_at timestamptz, submitted_at timestamptz, reviewed_at timestamptz, completed_at timestamptz, unique(task_id,employee_id));
create unique index task_assignment_recurring_unique on public.task_assignments(task_id,employee_id,instance_date) where instance_date is not null;
create index task_assignment_employee_status on public.task_assignments(employee_id,status); create index task_assignment_status on public.task_assignments(status); create index tasks_due_at on public.tasks(due_at) where archived_at is null;
create table public.submissions(id uuid primary key default gen_random_uuid(), task_assignment_id uuid not null references public.task_assignments(id) on delete cascade, response_text text, evidence_path text, checkbox_confirmed boolean not null default false, submitted_at timestamptz not null default now(), review_comment text, reviewed_by uuid references public.profiles(id) on delete set null, unique(task_assignment_id));
create table public.notifications(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, title text not null, body text not null, entity_type text, entity_id uuid, read_at timestamptz, created_at timestamptz not null default now()); create index notifications_user_created on public.notifications(user_id,created_at desc);
create table public.push_subscriptions(id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, token text not null, updated_at timestamptz not null default now(), unique(user_id,token));
create table public.task_templates(id uuid primary key default gen_random_uuid(), created_by uuid not null references public.profiles(id), title text not null, description text not null default '', priority public.task_priority not null default 'MEDIUM', submission_type public.submission_kind not null default 'CHECKBOX', department_id uuid references public.departments(id) on delete set null, created_at timestamptz not null default now());
create table public.task_recurrences(id uuid primary key default gen_random_uuid(), template_id uuid references public.task_templates(id) on delete set null, created_by uuid not null references public.profiles(id), title text not null, description text not null default '', priority public.task_priority not null default 'MEDIUM', submission_type public.submission_kind not null default 'CHECKBOX', assignee_ids uuid[] not null, department_id uuid references public.departments(id), frequency text not null check(frequency in ('DAILY','WEEKLY','MONTHLY')), local_time time not null, start_date date not null, end_date date, timezone text not null default 'UTC', last_generated_date date, active boolean not null default true, created_at timestamptz not null default now(), check(end_date is null or end_date>=start_date));
create table public.audit_logs(id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id) on delete set null, entity_type text not null, entity_id uuid not null, action text not null, details jsonb not null default '{}', created_at timestamptz not null default now());
create index audit_logs_created on public.audit_logs(created_at desc);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='ADMIN' and active) $$;
create or replace function public.current_department_id() returns uuid language sql stable security definer set search_path=public as $$ select department_id from profiles where id=auth.uid() $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,role) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','Restaurant team member'),'EMPLOYEE'); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
-- Create the initial admin by creating an Auth user then running as project owner: update profiles set role='ADMIN' where id=(select id from auth.users where email='owner@example.com');
create or replace function public.create_task_with_assignments(p_title text,p_description text,p_priority public.task_priority,p_due_at timestamptz,p_submission_type public.submission_kind,p_department_id uuid,p_assignee_ids uuid[]) returns uuid language plpgsql security definer set search_path=public as $$
declare tid uuid;
begin
 if not public.is_admin() then raise exception 'Only administrators can assign tasks'; end if;
 if length(trim(p_title)) not between 1 and 120 then raise exception 'Task title must be 1 to 120 characters'; end if;
 if coalesce(array_length(p_assignee_ids,1),0)=0 then raise exception 'Choose at least one active employee'; end if;
 if exists(select 1 from unnest(p_assignee_ids) x left join profiles p on p.id=x where p.id is null or not p.active or p.role<>'EMPLOYEE') then raise exception 'Assignees must be active employees'; end if;
 insert into tasks(title,description,department_id,assigned_by,priority,due_at,submission_type) values(trim(p_title),coalesce(p_description,''),p_department_id,auth.uid(),p_priority,p_due_at,p_submission_type) returning id into tid;
 insert into task_assignments(task_id,employee_id,department_id) select tid,p.id,p.department_id from profiles p where p.id=any(p_assignee_ids) on conflict(task_id,employee_id) do nothing;
 insert into notifications(user_id,title,body,entity_type,entity_id) select p.id,'New task assigned',trim(p_title),'task',tid from profiles p where p.id=any(p_assignee_ids);
 insert into audit_logs(actor_id,entity_type,entity_id,action,details) values(auth.uid(),'task',tid,'created',jsonb_build_object('assignees',p_assignee_ids)); return tid;
end $$;
create or replace function public.submit_task(p_assignment_id uuid,p_response_text text,p_evidence_path text,p_checkbox_confirmed boolean) returns void language plpgsql security definer set search_path=public as $$
declare a task_assignments; t tasks;
begin
 select * into a from task_assignments where id=p_assignment_id for update; if not found then raise exception 'Assignment not found'; end if;
 if a.employee_id<>auth.uid() then raise exception 'You can only submit your own work'; end if; select * into t from tasks where id=a.task_id;
 if a.status not in ('IN_PROGRESS','REJECTED') then raise exception 'This task cannot be submitted in its current state'; end if;
 if t.submission_type='TEXT' and length(trim(coalesce(p_response_text,'')))=0 then raise exception 'A written response is required'; end if;
 if t.submission_type='CAMERA' and (p_evidence_path is null or p_evidence_path not like auth.uid()::text||'/'||p_assignment_id::text||'/%') then raise exception 'A camera photo is required'; end if;
 if t.submission_type='CHECKBOX' and not p_checkbox_confirmed then raise exception 'Confirm task completion before submitting'; end if;
 insert into submissions(task_assignment_id,response_text,evidence_path,checkbox_confirmed,submitted_at,review_comment,reviewed_by) values(p_assignment_id,nullif(trim(p_response_text),''),p_evidence_path,p_checkbox_confirmed,now(),null,null) on conflict(task_assignment_id) do update set response_text=excluded.response_text,evidence_path=excluded.evidence_path,checkbox_confirmed=excluded.checkbox_confirmed,submitted_at=now(),review_comment=null,reviewed_by=null;
 update task_assignments set status='PENDING_APPROVAL',submitted_at=now() where id=p_assignment_id;
 insert into notifications(user_id,title,body,entity_type,entity_id) select id,'Task submitted for review',t.title,'assignment',p_assignment_id from profiles where role='ADMIN' and active;
 insert into audit_logs(actor_id,entity_type,entity_id,action) values(auth.uid(),'assignment',p_assignment_id,'submitted');
end $$;
create or replace function public.review_task(p_assignment_id uuid,p_decision text,p_comment text) returns void language plpgsql security definer set search_path=public as $$
declare a task_assignments; t tasks;
begin
 if not public.is_admin() then raise exception 'Only administrators can review tasks'; end if; if p_decision not in ('approve','reject') then raise exception 'Invalid review decision'; end if; if p_decision='reject' and length(trim(coalesce(p_comment,'')))=0 then raise exception 'Feedback is required when returning a task'; end if;
 select * into a from task_assignments where id=p_assignment_id for update; if not found or a.status not in ('PENDING_APPROVAL','SUBMITTED') then raise exception 'This submission is not awaiting review'; end if; select * into t from tasks where id=a.task_id;
 update task_assignments set status=case when p_decision='approve' then 'COMPLETED'::task_status else 'REJECTED'::task_status end,reviewed_at=now(),completed_at=case when p_decision='approve' then now() else null end where id=p_assignment_id;
 update submissions set review_comment=nullif(trim(p_comment),''),reviewed_by=auth.uid() where task_assignment_id=p_assignment_id;
 insert into notifications(user_id,title,body,entity_type,entity_id) values(a.employee_id,case when p_decision='approve' then 'Task approved' else 'Task returned for another try' end,t.title||case when p_decision='reject' then ': '||trim(p_comment) else '' end,'assignment',p_assignment_id);
 insert into audit_logs(actor_id,entity_type,entity_id,action,details) values(auth.uid(),'assignment',p_assignment_id,p_decision,jsonb_build_object('comment',p_comment));
end $$;
create or replace function public.advance_task(p_assignment_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin update task_assignments set status='IN_PROGRESS',started_at=now() where id=p_assignment_id and employee_id=auth.uid() and status='ASSIGNED'; if not found then raise exception 'Task cannot be started'; end if; insert into audit_logs(actor_id,entity_type,entity_id,action) values(auth.uid(),'assignment',p_assignment_id,'started'); end $$;
alter table profiles enable row level security; alter table departments enable row level security; alter table tasks enable row level security; alter table task_assignments enable row level security; alter table submissions enable row level security; alter table notifications enable row level security; alter table push_subscriptions enable row level security; alter table task_templates enable row level security; alter table task_recurrences enable row level security; alter table audit_logs enable row level security;
create policy "profiles visible to team" on profiles for select to authenticated using (id=auth.uid() or public.is_admin() or department_id=public.current_department_id()); create policy "admins manage profiles" on profiles for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "departments readable" on departments for select to authenticated using(true); create policy "admins manage departments" on departments for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "tasks visible to assigned staff" on tasks for select to authenticated using(public.is_admin() or exists(select 1 from task_assignments a where a.task_id=id and a.employee_id=auth.uid())); create policy "admins edit tasks" on tasks for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "assignments visible to owner or admin" on task_assignments for select to authenticated using(employee_id=auth.uid() or public.is_admin());
create policy "submissions visible to owner or admin" on submissions for select to authenticated using(public.is_admin() or exists(select 1 from task_assignments a where a.id=task_assignment_id and a.employee_id=auth.uid()));
create policy "notifications private" on notifications for select to authenticated using(user_id=auth.uid()); create policy "user marks notification read" on notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); revoke update on public.notifications from authenticated; grant update(read_at) on public.notifications to authenticated; create policy "push subscriptions private" on push_subscriptions for all to authenticated using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin());
create policy "templates admin only" on task_templates for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "recurrences admin only" on task_recurrences for all to authenticated using(public.is_admin()) with check(public.is_admin()); create policy "audit visible to admin or actor" on audit_logs for select to authenticated using(public.is_admin() or actor_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('task-evidence','task-evidence',false,5242880,array['image/jpeg']) on conflict(id) do nothing;
create policy "employees upload own evidence" on storage.objects for insert to authenticated with check(bucket_id='task-evidence' and (storage.foldername(name))[1]=auth.uid()::text); create policy "evidence readable by assignee and admins" on storage.objects for select to authenticated using(bucket_id='task-evidence' and (public.is_admin() or (storage.foldername(name))[1]=auth.uid()::text)); create policy "employees remove own evidence" on storage.objects for delete to authenticated using(bucket_id='task-evidence' and (storage.foldername(name))[1]=auth.uid()::text);
grant execute on function public.create_task_with_assignments(text,text,task_priority,timestamptz,submission_kind,uuid,uuid[]) to authenticated; grant execute on function public.submit_task(uuid,text,text,boolean) to authenticated; grant execute on function public.review_task(uuid,text,text) to authenticated; grant execute on function public.advance_task(uuid) to authenticated;
